package org.tvshell.iptvnator.backend;

import static org.tvshell.iptvnator.backend.TestMain.assertEquals;
import static org.tvshell.iptvnator.backend.TestMain.assertTrue;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.Charset;
import java.util.List;
import java.util.Map;

/**
 * The Java parser must produce exactly what the JavaScript fork produces:
 * every fixture in src/test/resources/m3u-fixtures was generated by running
 * the real iptv-playlist-parser (tools/gen-parser-fixtures.mjs).
 */
public class M3uParserTest {

    private static final Charset UTF8 = Charset.forName("UTF-8");

    static String resource(String name) throws IOException {
        InputStream in = M3uParserTest.class.getResourceAsStream("/m3u-fixtures/" + name);
        if (in == null) throw new IOException("missing fixture " + name);
        try {
            java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int read;
            while ((read = in.read(buffer)) != -1) out.write(buffer, 0, read);
            return new String(out.toByteArray(), UTF8);
        } finally {
            in.close();
        }
    }

    /** Structural equality, independent of key order and of int/float lexical forms. */
    @SuppressWarnings("unchecked")
    static String diff(Object expected, Object actual, String path) {
        if (expected instanceof Map) {
            if (!(actual instanceof Map)) return path + ": expected object, got " + actual;
            Map<String, Object> e = (Map<String, Object>) expected;
            Map<String, Object> a = (Map<String, Object>) actual;
            for (String key : e.keySet()) {
                if (!a.containsKey(key)) return path + "." + key + ": missing (expected " + Json.write(e.get(key)) + ")";
                String d = diff(e.get(key), a.get(key), path + "." + key);
                if (d != null) return d;
            }
            for (String key : a.keySet()) {
                if (!e.containsKey(key)) return path + "." + key + ": unexpected key (" + Json.write(a.get(key)) + ")";
            }
            return null;
        }
        if (expected instanceof List) {
            if (!(actual instanceof List)) return path + ": expected array, got " + actual;
            List<Object> e = (List<Object>) expected;
            List<Object> a = (List<Object>) actual;
            if (e.size() != a.size()) return path + ": expected " + e.size() + " items, got " + a.size();
            for (int i = 0; i < e.size(); i++) {
                String d = diff(e.get(i), a.get(i), path + "[" + i + "]");
                if (d != null) return d;
            }
            return null;
        }
        if (expected instanceof Number && actual instanceof Number) {
            if (((Number) expected).doubleValue() != ((Number) actual).doubleValue()) return path + ": expected " + expected + ", got " + actual;
            return null;
        }
        if (expected == null ? actual != null : !expected.equals(actual)) {
            return path + ": expected " + Json.write(expected) + ", got " + Json.write(actual);
        }
        return null;
    }

    @SuppressWarnings("unchecked")
    public void testAllFixturesMatchTheJavaScriptParser() throws IOException {
        String[] names = resource("index.txt").trim().split("\n");
        assertTrue("fixtures present", names.length >= 40);
        int checked = 0;
        for (String name : names) {
            name = name.trim();
            if (name.isEmpty()) continue;
            String input = resource(name + ".m3u");
            Map<String, Object> expected = (Map<String, Object>) Json.parse(resource(name + ".expected.json"));
            boolean expectedOk = Boolean.TRUE.equals(expected.get("ok"));
            if (expectedOk) {
                Map<String, Object> actual;
                try {
                    actual = M3uParser.parse(input);
                } catch (RuntimeException e) {
                    throw new TestMain.AssertionFailed(name + ": parser threw " + e);
                }
                // Re-read our own output through the JSON writer so both sides
                // are compared as JSON values.
                Object roundTripped = Json.parse(Json.write(actual));
                String d = diff(expected.get("result"), roundTripped, name);
                if (d != null) throw new TestMain.AssertionFailed(d);
            } else {
                try {
                    M3uParser.parse(input);
                    throw new TestMain.AssertionFailed(name + ": expected an error (" + expected.get("error") + ")");
                } catch (M3uParser.InvalidPlaylistException e) {
                    assertEquals(name + " error message", expected.get("error"), e.getMessage());
                }
            }
            checked++;
        }
        System.out.println("       " + checked + " fixtures compared");
    }

    /** Lines(): what content.split("\\r?\\n", -1) gives, one at a time, without the String[]. */
    public void testLinesMatchSplitSemantics() {
        String[] samples = {"", "a", "a\n", "a\nb", "a\r\nb\r\n", "\n\n", "a\rb\n", "\r\n", "x\n\r\n\ny\r"};
        for (String text : samples) {
            String[] expected = text.split("\r?\n", -1);
            M3uParser.Lines lines = new M3uParser.Lines(text);
            for (int i = 0; i < expected.length; i++) {
                assertEquals("line " + i + " of " + text.replace("\r", "\\r").replace("\n", "\\n"), expected[i], lines.next());
                assertEquals("index " + i, Integer.valueOf(i), Integer.valueOf(lines.index));
            }
            assertEquals("end of " + text.replace("\r", "\\r").replace("\n", "\\n"), null, lines.next());
        }
    }

    @SuppressWarnings("unchecked")
    public void testLineNumbersSurviveBlankLinesAndLineEndings() {
        Map<String, Object> parsed = M3uParser.parse("\r\n\n#EXTM3U\r\n\r\n#EXTINF:-1,One\r\nhttp://a/1\n\n#EXTINF:-1,Two\nhttp://a/2\n");
        List<Object> items = (List<Object>) parsed.get("items");
        assertEquals("two items", 2, Integer.valueOf(items.size()));
        assertEquals("first line number", Integer.valueOf(5), ((Map<String, Object>) items.get(0)).get("line"));
        assertEquals("second line number", Integer.valueOf(8), ((Map<String, Object>) items.get(1)).get("line"));
        assertEquals("raw keeps both lines", "#EXTINF:-1,One\r\nhttp://a/1", ((Map<String, Object>) items.get(0)).get("raw"));
    }

    public void testJsTrimStripsBomAndUnicodeSpaces() {
        assertEquals("bom", "x", M3uParser.jsTrim("﻿x "));
        assertEquals("tabs", "a b", M3uParser.jsTrim("\t a b \r\n"));
        assertEquals("ideographic", "y", M3uParser.jsTrim("　y "));
    }
}
